#!/usr/bin/env python3
"""
Parse Wikidata-style coordinates and produce a clean POI table.
"""

import json
import csv
import re
import os

def parse_wikidata_coord(coord_str):
    """
    Parse Wikidata coordinate string to latitude and longitude.

    Wikidata coordinates come in formats like:
    - "52.520006;13.404954;0" (lat;lon;elevation)
    - "52.520006;13.404954" (lat;lon)
    - "+52.52000600;+13.40495400" (with signs)
    - "52°31′12″N 13°24′17″E" (DMS format - less common in machine data)

    Returns (latitude, longitude) as floats or (None, None) if parsing fails.
    """
    if not coord_str:
        return None, None

    # Try semicolon-separated format first (most common in Wikidata JSON)
    parts = coord_str.split(';')
    if len(parts) >= 2:
        try:
            lat = float(parts[0].strip())
            lon = float(parts[1].strip())

            # Validate ranges
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return lat, lon
        except (ValueError, TypeError):
            pass

    # Try DMS format (degrees, minutes, seconds)
    # Pattern like: 52°31′12″N 13°24′17″E
    dms_pattern = r'([+-]?\d+)\s*°\s*(\d+)\s*′\s*(\d+(?:\.\d+)?)\s*([NS])\s+([+-]?\d+)\s*°\s*(\d+)\s*′\s*(\d+(?:\.\d+)?)\s*([EW])'
    match = re.match(dms_pattern, coord_str)
    if match:
        try:
            lat_deg = float(match.group(1))
            lat_min = float(match.group(2))
            lat_sec = float(match.group(3))
            lat_dir = match.group(4)

            lon_deg = float(match.group(5))
            lon_min = float(match.group(6))
            lon_sec = float(match.group(7))
            lon_dir = match.group(8)

            lat = lat_deg + lat_min/60 + lat_sec/3600
            if lat_dir == 'S':
                lat = -lat

            lon = lon_deg + lon_min/60 + lon_sec/3600
            if lon_dir == 'W':
                lon = -lon

            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return lat, lon
        except (ValueError, TypeError):
            pass

    return None, None

def extract_poi_type(item):
    """
    Extract POI type from Wikidata item.
    Look for common type properties or labels.
    """
    # Check if there's a type in the item data
    # Common patterns in Wikidata JSON exports
    if isinstance(item, dict):
        # Check for explicit type field
        if 'type' in item:
            return item['type']
        if 'poi_type' in item:
            return item['poi_type']

        # Check for P31 (instance of) property
        if 'claims' in item:
            claims = item['claims']
            if isinstance(claims, dict):
                # P31 is "instance of"
                p31_data = claims.get('P31', [])
                if isinstance(p31_data, list) and len(p31_data) > 0:
                    # Get the first instance of
                    first_claim = p31_data[0]
                    if isinstance(first_claim, dict):
                        # Could be a nested structure
                        if 'mainsnak' in first_claim:
                            mainsnak = first_claim['mainsnak']
                            if 'datavalue' in mainsnak:
                                return mainsnak['datavalue'].get('value', {}).get('text', 'unknown')
                        elif 'value' in first_claim:
                            val = first_claim['value']
                            if isinstance(val, dict):
                                return val.get('text', val.get('id', 'unknown'))
                            return str(val)

        # Check for a 'properties' section
        if 'properties' in item:
            props = item['properties']
            if isinstance(props, dict):
                p31_data = props.get('P31', [])
                if isinstance(p31_data, list) and len(p31_data) > 0:
                    first_claim = p31_data[0]
                    if isinstance(first_claim, dict):
                        if 'datavalue' in first_claim:
                            return first_claim['datavalue'].get('value', {}).get('text', 'unknown')

        # Check for 'about' section with type info
        if 'about' in item and isinstance(item['about'], dict):
            if 'type' in item['about']:
                return item['about']['type']

    return 'unknown'

def process_wikidata_pois(input_path, output_path):
    """
    Process Wikidata POI JSON and output clean CSV.
    """
    # Read input JSON
    with open(input_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    pois = []

    # Handle different JSON structures
    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        # Could have 'items' key or be a single item
        if 'items' in data:
            items = data['items']
        elif 'entities' in data:
            items = list(data['entities'].values())
        else:
            # Single item, wrap in list
            items = [data]
    else:
        items = []

    seen_qids = set()

    for item in items:
        if not isinstance(item, dict):
            continue

        # Extract qid
        qid = None
        if 'qid' in item:
            qid = item['qid']
        elif 'id' in item:
            qid = item['id']
        elif 'about' in item and isinstance(item['about'], dict) and 'id' in item['about']:
            qid = item['about']['id']

        # qid might be in format "Q123" or just "123"
        if qid:
            qid = str(qid)
            if not qid.startswith('Q'):
                qid = 'Q' + qid

        if not qid:
            continue

        # Skip duplicates
        if qid in seen_qids:
            continue
        seen_qids.add(qid)

        # Extract label
        label = None
        if 'label' in item:
            label = item['label']
        elif 'itemLabel' in item:
            label = item['itemLabel']
        elif 'labels' in item and isinstance(item['labels'], dict):
            # Labels might be in multiple languages
            labels = item['labels']
            # Try English first, then any available
            if 'en' in labels:
                label = labels['en'].get('value', '')
            elif 'en-gb' in labels:
                label = labels['en-gb'].get('value', '')
            else:
                for lang, val in labels.items():
                    if isinstance(val, dict) and 'value' in val:
                        label = val['value']
                        break

        # Fallback to qid if label is missing or empty
        if not label or not str(label).strip():
            label = qid

        # Extract coordinates
        lat = None
        lon = None

        coord_str = None
        if 'coords' in item:
            coord_str = item['coords']
        elif 'coordinates' in item:
            coord_str = item['coordinates']
        elif 'coords' in item.get('about', {}):
            coord_str = item['about']['coords']
        elif 'coordinates' in item.get('about', {}):
            coord_str = item['about']['coordinates']
        elif 'claims' in item:
            # Check for P625 (coordinate location) property
            claims = item['claims']
            if isinstance(claims, dict):
                p625_data = claims.get('P625', [])
                if isinstance(p625_data, list) and len(p625_data) > 0:
                    first_claim = p625_data[0]
                    if isinstance(first_claim, dict):
                        if 'mainsnak' in first_claim:
                            mainsnak = first_claim['mainsnak']
                            if 'datavalue' in mainsnak:
                                coord_str = mainsnak['datavalue'].get('value', {}).get('text', '')
                        elif 'value' in first_claim:
                            val = first_claim['value']
                            if isinstance(val, dict):
                                coord_str = val.get('text', '')
                            else:
                                coord_str = str(val)

        # Also check for nested coordinate structure
        if not coord_str and isinstance(item, dict):
            for key in ['coords', 'coordinates', 'coord', 'coordinate']:
                if key in item:
                    val = item[key]
                    if isinstance(val, dict):
                        # Could be {"lat": ..., "lon": ...} or {"latitude": ..., "longitude": ...}
                        lat_val = val.get('lat') or val.get('latitude') or val.get('Lat') or val.get('Latitude')
                        lon_val = val.get('lon') or val.get('longitude') or val.get('Lon') or val.get('Longitude')
                        if lat_val is not None and lon_val is not None:
                            lat = float(lat_val)
                            lon = float(lon_val)
                            break
                    elif isinstance(val, str):
                        coord_str = val
                        break
                    elif isinstance(val, (list, tuple)) and len(val) >= 2:
                        lat = float(val[0])
                        lon = float(val[1])
                        break

        # Parse coordinate string if we have one
        if coord_str and lat is None:
            lat, lon = parse_wikidata_coord(coord_str)

        # Validate coordinates
        if lat is not None and lon is not None:
            if not (-90 <= lat <= 90 and -180 <= lon <= 180):
                lat = None
                lon = None

        # Extract POI type
        poi_type = extract_poi_type(item)

        # Only add if we have valid coordinates
        if lat is not None and lon is not None:
            pois.append({
                'qid': qid,
                'label': label,
                'poi_type': poi_type,
                'latitude': lat,
                'longitude': lon,
                'source': 'wikidata'
            })

    # Ensure output directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    # Write CSV output
    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source'])
        writer.writeheader()
        writer.writerows(pois)

    print(f"Processed {len(pois)} POIs from Wikidata")
    print(f"Output written to: {output_path}")

if __name__ == '__main__':
    input_path = 'inputs/wikidata/wikidata_pois_sample.json'
    output_path = 'outputs/t08_pois_clean.csv'

    process_wikidata_pois(input_path, output_path)
